property.value:
%clr(%d{yyyy-MM-dd HH:mm:ss}){faint}
               %clr(%-5level){
                   ERROR=red,
                   WARN=yellow,
                   INFO=green,
                   DEBUG=cyan,
                   TRACE=blue
               }
               %clr([%thread]){magenta}
               %clr(%logger{36}){blue}
               - %msg%n
